class Solution:
    def maxSumTwoNoOverlap(self, nums: List[int], firstLen: int, secondLen: int) -> int:
        n = len(nums)
        p = [0]
        for el in nums:
            p.append(p[-1] + el)
        msum = 0
        for f, s in [(firstLen, secondLen), (secondLen, firstLen)]:
            for i in range(f - 1, n - s + 1):
                for j in range(i + 1, n - s + 1):
                    l = p[i + 1] - p[i - f + 1]
                    r = p[j + s] - p[j]
                    msum = max(msum, l + r)
        return msum

class Solution:
    def maxSumTwoNoOverlap(self, A, L, M):
        for i in range(1, len(A)):
            A[i] += A[i-1]
        result, L_max, M_max = A[L+M-1], A[L-1], A[M-1]
        for i in range(L+M, len(A)):
            L_max = max(L_max, A[i-M] - A[i-L-M])
            M_max = max(M_max, A[i-L] - A[i-L-M])
            result = max(result,
                         L_max + A[i] - A[i-M],
                         M_max + A[i] - A[i-L])
        return result

