class Solution:
    def maxUncrossedLines(self, nums1: List[int], nums2: List[int]) -> int:

        @lru_cache(None)
        def dp(a,b):
            if a>=len(nums1) or b>=len(nums2): return 0
            if nums1[a]==nums2[b]: return 1+dp(a+1,b+1)
            else: return max(dp(a+1,b),dp(a,b+1))

        return dp(0,0)

class Solution:
    def maxUncrossedLines(self, A, B):
        if len(A) < len(B):
            return self.maxUncrossedLines(B, A)

        dp = [[0 for _ in range(len(B)+1)] for _ in range(2)]
        for i in range(len(A)):
            for j in range(len(B)):
                dp[(i+1)%2][j+1] = max(dp[i%2][j] + int(A[i] == B[j]),
                                       dp[i%2][j+1],
                                       dp[(i+1)%2][j])
        return dp[len(A)%2][len(B)]

